function validate([coins, target]) {
  if (!Number.isInteger(target) || target < 1 || target > 100000) return 'target is an integer from 1 to 100000.';
  if (!Array.isArray(coins) || coins.length < 1 || coins.length > 100000) return 'coins needs 1 to 100000 values.';
  if (coins.some(v => !Number.isInteger(v) || v < 1 || v > target)) return 'Each coin is an integer from 1 to target.';
  return null;
}

