function minimumAddedCoins(coins, target) {
  coins.sort((a, b) => a - b);
  let reach = 0;
  let added = 0;
  let index = 0;

  while (reach < target) {
    if (index < coins.length && coins[index] <= reach + 1) {
      reach += coins[index];
      index++;
    } else {
      reach += reach + 1;
      added++;
    }
  }
  return added;
}

