function minimumAddedCoins(coins, target) {
  // Recompute every payable amount with a subset-sum table, then add the smallest amount still missing.
  const all = coins.slice();
  for (let added = 0; ; added++) {
    const payable = new Uint8Array(target + 1);
    payable[0] = 1;
    for (const value of all) {
      for (let sum = target; sum >= value; sum--) if (payable[sum - value]) payable[sum] = 1;
    }
    let missing = 1;
    while (missing <= target && payable[missing]) missing++;
    if (missing > target) return added;
    all.push(missing);
  }
}

