function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const target = pick(1, 22);
    const n = pick(1, 6);
    const coins = Array.from({ length: n }, () => (rand() < 0.3 ? pick(1, Math.min(3, target)) : pick(1, target)));
    return [coins, target];
  }
  const target = pick(50000, 100000);
  const mode = pick(0, 2);
  const n = mode === 2 ? pick(1, 20) : pick(1000, 2000);
  const coins = Array.from({ length: n }, () => {
    if (mode === 0) return pick(1, target);
    if (mode === 1) return 1 + Math.floor(target * rand() ** 4) % target;
    return pick(Math.floor(target / 4), target);
  });
  return [coins, target];
}
